<?php require 'db.php'; require 'helpers.php'; if(!empty($_SESSION['user'])){header('Location: '.(($_SESSION['user']['role']??'')==='admin'?'admin.php':'home.php'));exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$login=trim($_POST['login']??'');$pw=$_POST['password']??'';$s=$pdo->prepare("SELECT * FROM users WHERE (email=? OR username=?) AND role='student' AND status='active' LIMIT 1");$s->execute([$login,$login]);$u=$s->fetch();if($u&&password_verify($pw,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>'student'];$_SESSION['last_activity']=time();$pdo->prepare('UPDATE users SET last_login=NOW() WHERE id=?')->execute([$u['id']]);audit($pdo,'student_login','Successful student login');header('Location: home.php');exit;}$err='The student email/username or password is incorrect.';}page_header('Student Login');if(isset($_GET['timeout']))echo '<div class="error">Your session expired. Please sign in again.</div>';if(isset($_GET['disabled']))echo '<div class="error">This student account is currently inactive or deleted. Contact the administrator.</div>';if($err)echo '<div class="error">'.e($err).'</div>'; ?>
